import { describe, expect, it } from 'vitest';
import { createCodexAppServerEventMapper } from './codexAppServerEvents.js';

// Fixtures follow the native v2 schema generated by codex-cli 0.166.0, not exec --json.
const startTurn = (id = 'turn-1') => ({ threadId: 'thread-1', turn: { id, status: 'inProgress', items: [] } });
const endTurn = (items: unknown[] = [], id = 'turn-1') => ({ threadId: 'thread-1', turn: { id, status: 'completed', items } });
const itemParams = (item: unknown) => ({ threadId: 'thread-1', turnId: 'turn-1', item });
const tokens = (inputTokens: number, outputTokens = 10, cachedInputTokens = 20, reasoningOutputTokens = 2) =>
  ({ inputTokens, outputTokens, cachedInputTokens, reasoningOutputTokens });
const tokenUpdate = (total: ReturnType<typeof tokens>, last = total) =>
  ({ threadId: 'thread-1', turnId: 'turn-1', tokenUsage: { total, last, modelContextWindow: 200_000 } });

describe('native notification boundaries', () => {
  it('maps thread identity and keeps unknown or malformed notifications out of the UI', () => {
    const mapper = createCodexAppServerEventMapper();
    expect(mapper.map('thread/started', { thread: { id: 'thread-1' } })).toEqual({ events: [], threadId: 'thread-1' });
    expect(mapper.map('not/a/method', {})).toBeNull();
    expect(mapper.map('item/completed', { item: 'bad' })).toBeNull();
    expect(mapper.map('item/completed', null)).toBeNull();
    expect(mapper.map('item/completed', itemParams({ id: 'x', type: 'futureType' }))).toBeNull();
  });

  it('commits text once per item; deltas and completed commentary never end the turn', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    const message = { id: 'message-1', type: 'agentMessage', phase: 'commentary', text: 'Inspecting the implementation.' };
    expect(mapper.map('item/started', itemParams(message))).toEqual({ events: [] });
    expect(mapper.map('item/agentMessage/delta', { itemId: message.id, delta: 'Inspecting' })).toEqual({ events: [] });
    expect(mapper.map('item/completed', itemParams(message))).toEqual({
      events: [{ eventType: 'text', content: message.text }],
    });
    expect(mapper.map('item/completed', itemParams(message))).toEqual({ events: [] });
    expect(mapper.map('turn/completed', endTurn([message]))).toEqual({ events: [], turnEnded: true });
  });

  it.each(['commentary', 'partial_answer', 'future_phase'])('does not treat phase %s as the final answer', phase => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    mapper.map('item/completed', itemParams({ id: 'm', type: 'agentMessage', text: 'Continuing.', phase }));
    expect(mapper.map('turn/completed', endTurn())?.finalText).toBeUndefined();
  });

  it.each(['final_answer', null, undefined])('preserves final and legacy phase %s without ending on an item', phase => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    const result = mapper.map('item/completed', itemParams({ id: 'm', type: 'agentMessage', text: 'Implemented.', phase }));
    expect(result?.finalText).toBe('Implemented.');
    expect(result?.turnEnded).toBeUndefined();
    expect(mapper.map('turn/completed', endTurn())).toEqual({ events: [], turnEnded: true, finalText: 'Implemented.' });
  });

  it('keeps async notifications visible without replacing the final answer', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    mapper.map('item/completed', itemParams({ id: 'm1', type: 'agentMessage', text: 'Done.', phase: 'final_answer' }));
    const async = mapper.map('item/completed', itemParams({ id: 'm2', type: 'agentMessage', text: 'Background update', phase: 'final_answer', delivery: 'async' }));
    expect(async?.events[0]?.content).toBe('Background update');
    expect(async?.finalText).toBeUndefined();
    expect(mapper.map('turn/completed', endTurn())?.finalText).toBe('Done.');
  });

  it('recovers snapshot-only items and ignores replayed turn starts and completions', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    const first = { id: 'm1', type: 'agentMessage', phase: 'commentary', text: 'Working.' };
    mapper.map('item/completed', itemParams(first));
    mapper.map('turn/started', startTurn());
    const last = { id: 'm2', type: 'agentMessage', phase: 'final_answer', text: 'Finished.' };
    const terminal = endTurn([first, last]);
    expect(mapper.map('turn/completed', terminal)).toEqual({
      events: [{ eventType: 'text', content: 'Finished.' }], turnEnded: true, finalText: 'Finished.',
    });
    expect(mapper.map('turn/completed', terminal)).toEqual({ events: [] });
    expect(mapper.map('turn/started', startTurn())).toEqual({ events: [] });
    mapper.map('turn/started', startTurn('turn-2'));
    expect(mapper.map('turn/completed', endTurn([], 'turn-2'))).toEqual({ events: [], turnEnded: true });
  });

  it('uses reasoning summaries and falls back to available reasoning content', () => {
    const mapper = createCodexAppServerEventMapper();
    expect(mapper.map('item/completed', itemParams({ id: 'r1', type: 'reasoning', summary: ['First', 'Second'], content: ['Raw'] }))?.events)
      .toEqual([{ eventType: 'thinking', content: 'First\nSecond' }]);
    expect(mapper.map('item/completed', itemParams({ id: 'r2', type: 'reasoning', summary: [], content: ['Available content'] }))?.events)
      .toEqual([{ eventType: 'thinking', content: 'Available content' }]);
  });
});

describe('native tools and progress', () => {
  it('preserves command hooks, command identity, output and explicit success', () => {
    const mapper = createCodexAppServerEventMapper();
    const item = { id: 'cmd', type: 'commandExecution', command: 'pnpm test', status: 'inProgress' };
    expect(mapper.map('item/started', itemParams(item))?.events).toEqual([{
      eventType: 'tool_use', toolName: 'Bash', toolUseId: 'cmd', content: 'pnpm test',
      bashHook: { phase: 'pre', command: 'pnpm test' },
    }]);
    const result = mapper.map('item/completed', itemParams({ id: 'cmd', type: 'commandExecution', status: 'completed', exitCode: 0, aggregatedOutput: 'passed' }));
    expect(result?.events).toEqual([{
      eventType: 'tool_result', toolName: 'Bash', toolUseId: 'cmd', content: 'exit 0\npassed',
      bashHook: { phase: 'post', command: 'pnpm test', toolResponse: 'passed', toolIsError: false },
    }]);
    expect(result?.turnEnded).toBeUndefined();
  });

  it.each(['failed', 'declined', 'interrupted'])('keeps %s command execution unsuccessful without ending the turn', status => {
    const mapper = createCodexAppServerEventMapper();
    const result = mapper.map('item/completed', itemParams({ id: 'cmd', type: 'commandExecution', status, exitCode: null, aggregatedOutput: '' }));
    expect(result?.events[0]?.bashHook?.toolIsError).toBe(true);
    expect(result?.turnEnded).toBeUndefined();
  });

  it('does not invent command success from output or a missing exit code', () => {
    const mapper = createCodexAppServerEventMapper();
    const result = mapper.map('item/completed', itemParams({ id: 'cmd', type: 'commandExecution', status: 'completed', aggregatedOutput: 'all good' }));
    expect(result?.events[0]?.bashHook?.toolIsError).toBeUndefined();
  });

  it('reports successful file changes and renames once, and preserves failed patch results', () => {
    const mapper = createCodexAppServerEventMapper();
    const changes = [{ path: 'old.ts', kind: { type: 'update', move_path: 'new.ts' }, diff: '' }, { path: 'new.ts', kind: { type: 'add' }, diff: '' }];
    expect(mapper.map('item/started', itemParams({ id: 'f1', type: 'fileChange', changes, status: 'inProgress' }))?.fileWrites).toBeUndefined();
    expect(mapper.map('item/completed', itemParams({ id: 'f1', type: 'fileChange', changes, status: 'completed' }))?.fileWrites).toEqual(['old.ts', 'new.ts']);
    const failed = mapper.map('item/completed', itemParams({ id: 'f2', type: 'fileChange', changes, status: 'declined' }));
    expect(failed?.fileWrites).toBeUndefined();
    expect(failed?.events[0]?.content).toContain('failed');
    expect(failed?.turnEnded).toBeUndefined();
  });

  it('pairs MCP calls with result obligations and preserves tool errors without ending the turn', () => {
    const mapper = createCodexAppServerEventMapper();
    const call = { id: 'mcp', type: 'mcpToolCall', server: 'docs', tool: 'search', arguments: { query: 'app server' }, status: 'inProgress' };
    expect(mapper.map('item/started', itemParams(call))?.events).toEqual([{
      eventType: 'tool_use', toolName: 'docs:search', toolUseId: 'mcp', awaitsResult: true, content: '{"query":"app server"}',
    }]);
    const failed = mapper.map('item/completed', itemParams({ ...call, status: 'failed', result: null, error: { message: 'Unavailable' } }));
    expect(failed?.events).toEqual([{ eventType: 'tool_result', toolName: 'docs:search', toolUseId: 'mcp', content: 'failed\nUnavailable' }]);
    expect(failed?.turnEnded).toBeUndefined();
    const result = { content: [{ type: 'text', text: 'Documentation' }], structuredContent: { count: 1 } };
    expect(mapper.map('item/completed', itemParams({ ...call, id: 'mcp2', status: 'completed', result, error: null }))?.events[0]?.content)
      .toBe(JSON.stringify(result));
  });

  it('keeps web actions and image paths in the existing event protocol', () => {
    const mapper = createCodexAppServerEventMapper('win32');
    expect(mapper.map('item/completed', itemParams({ id: 'w', type: 'webSearch', action: { type: 'openPage', url: 'https://example.com' } }))?.events)
      .toEqual([{ eventType: 'tool_result', toolName: 'WebSearch', toolUseId: 'w', content: 'open: https://example.com' }]);
    expect(mapper.map('item/completed', itemParams({ id: 'image', type: 'imageView', path: 'file:///C:/My%20Images/test.png' }))?.events)
      .toEqual([{ eventType: 'text', content: 'test.png', imagePath: 'C:/My Images/test.png' }]);
  });

  it('maps plans without treating a checked plan as turn completion', () => {
    const mapper = createCodexAppServerEventMapper();
    expect(mapper.map('turn/plan/updated', { plan: [
      { step: 'Read', status: 'completed' }, { step: 'Implement', status: 'inProgress' }, { step: 'Test', status: 'pending' },
    ] })).toEqual({ events: [{ eventType: 'system', content: '[x] Read\n[~] Implement\n[ ] Test' }] });
  });

  it('exposes compaction and native agent wait state without manufacturing a final answer', () => {
    const mapper = createCodexAppServerEventMapper();
    for (const [method, active] of [['item/started', true], ['item/completed', false]] as const) {
      expect(mapper.map(method, itemParams({ id: 'compact', type: 'contextCompaction' })))
        .toEqual({ events: [], progress: { kind: 'compaction', active } });
      const wait = mapper.map(method, itemParams({ id: 'wait', type: 'collabAgentToolCall', tool: 'wait', receiverThreadIds: ['child'], agentsStates: {} }));
      expect(wait?.progress).toEqual({ kind: 'agentWait', active, toolUseId: 'wait' });
      expect(wait?.turnEnded).toBeUndefined();
    }
  });
});

describe('native failures and turn usage', () => {
  it('shows retryable errors as notices and lets only the terminal status fail the turn', () => {
    const mapper = createCodexAppServerEventMapper();
    expect(mapper.map('error', { willRetry: true, error: { message: 'Reconnecting' } }))
      .toEqual({ events: [{ eventType: 'system', content: 'Reconnecting' }] });
    expect(mapper.map('error', { willRetry: false, error: { message: 'Request failed' } })?.turnEnded).toBeUndefined();
    expect(mapper.map('turn/completed', { turn: { id: 't', status: 'failed', error: { message: 'Request failed' }, items: [] } }))
      .toEqual({ events: [], turnEnded: true, error: 'Request failed' });
  });

  it('does not report interrupted or still-running turns as completed successfully', () => {
    const mapper = createCodexAppServerEventMapper();
    expect(mapper.map('turn/completed', { turn: { id: 't', status: 'inProgress', items: [] } })).toBeNull();
    expect(mapper.map('turn/completed', { turn: { id: 't', status: 'interrupted', items: [] } }))
      .toEqual({ events: [], turnEnded: true, error: 'Codex turn interrupted' });
  });

  it('does not fabricate tool results for unfinished items in an interrupted snapshot', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    const pending = { id: 'mcp', type: 'mcpToolCall', server: 'docs', tool: 'search', status: 'inProgress', result: null };
    mapper.map('item/started', itemParams(pending));
    expect(mapper.map('turn/completed', { turn: { id: 'turn-1', status: 'interrupted', items: [pending] } }))
      .toEqual({ events: [], turnEnded: true, error: 'Codex turn interrupted' });
  });

  it('accumulates only this turn once, excluding resumed historical tokens and duplicate snapshots', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    const first = tokenUpdate(tokens(1_100, 110, 220, 22), tokens(100, 10, 20, 2));
    expect(mapper.map('thread/tokenUsage/updated', first)).toEqual({ events: [] });
    mapper.map('thread/tokenUsage/updated', first);
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(1_250, 130, 260, 24), tokens(150, 20, 40, 2)));
    expect(mapper.map('turn/completed', endTurn())?.usage).toEqual(tokens(250, 30, 60, 4));
    expect(mapper.map('turn/completed', endTurn())).toEqual({ events: [] });
    mapper.map('turn/started', startTurn('turn-2'));
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(1_300, 140, 270, 25), tokens(50, 10, 10, 1)));
    expect(mapper.map('turn/completed', endTurn([], 'turn-2'))?.usage).toEqual(tokens(50, 10, 10, 1));
  });

  it('uses a known pre-turn total baseline and ignores malformed or regressed snapshots', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(1_000, 100, 200, 20)));
    mapper.map('turn/started', startTurn());
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(1_100, 110, 220, 22), tokens(100, 10, 20, 2)));
    // The input count grows but the output counter regresses: ignore the entire replay.
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(1_200, 105, 230, 23)));
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(-1, 120, 240, 24)));
    mapper.map('thread/tokenUsage/updated', { tokenUsage: { total: { inputTokens: '1500' } } });
    mapper.map('thread/tokenUsage/updated', tokenUpdate(tokens(1_250, 130, 260, 24)));
    expect(mapper.map('turn/completed', endTurn())?.usage).toEqual(tokens(250, 30, 60, 4));
  });

  it('does not manufacture usage when the server provides none', () => {
    const mapper = createCodexAppServerEventMapper();
    mapper.map('turn/started', startTurn());
    expect(mapper.map('turn/completed', endTurn())?.usage).toBeUndefined();
  });
});
